const CURRENT = "omnimind:composer-drafts:g1";
export function readOrCreateComposerDraftEnvelope(storage: Storage) {
  const retiredV1 = storage.getItem("omnimind:composer-drafts:v1");
  const retiredV2 = storage.getItem("omnimind:composer-drafts:v2");
  if (retiredV1 !== null || retiredV2 !== null) {
    throw new Error("PREBASELINE_RESET_REQUIRED");
  }
  const current = storage.getItem(CURRENT);
  if (current === null) storage.setItem(CURRENT, JSON.stringify({ generation: 1, state: {} }));
  const reread = storage.getItem(CURRENT);
  storage.setItem(CURRENT, reread ?? "");
  return reread;
}
